function twoTradeProfit(prices: number[]): number {
  const one = (lo: number, hi: number): number => {
    let low = Infinity, best = 0;
    for (let i = lo; i < hi; i++) {
      low = Math.min(low, prices[i]);
      best = Math.max(best, prices[i] - low);
    }
    return best;
  };
  let best = 0;
  for (let d = 0; d < prices.length; d++) best = Math.max(best, one(0, d + 1) + one(d, prices.length));
  return best;
}

