function twoTradeProfit(prices: number[]): number {
  const n = prices.length;
  const left = new Array(n).fill(0), right = new Array(n).fill(0);
  let low = prices[0];
  for (let i = 1; i < n; i++) {
    low = Math.min(low, prices[i]);
    left[i] = Math.max(left[i - 1], prices[i] - low);
  }
  let high = prices[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    high = Math.max(high, prices[i]);
    right[i] = Math.max(right[i + 1], high - prices[i]);
  }
  let best = 0;
  for (let i = 0; i < n; i++) best = Math.max(best, left[i] + right[i]);
  return best;
}

